% Generate graded TMPS

% =========================================================================
%
% In the first section of the code the 3D binary image is generated by
% setting the number of repetitive cells (c), the pixels per edge (n), 
% and the two parameters affecting the porosity (b and errore). 
% The geometry list displays the available TPMS geometries
%
% In the second section the image is saved as tiff file.

clearvars
clc

% Dimensioni
c = 4;
n = c*50+1;

% Geometrie disponibili
geometryList = {'Gyroid','Diamond','Primitive','IWP','Nevious'};

% Selezione delle strutture da collegare
structures = {'Diamond','Diamond'};

% Numero di strutture da collegare
nStructures = size(structures,2);

% Parametri iniziali e finali
b_start = 2.5;
b_end = 2.5;

errore_start = 3.01;
errore_end = 1.5;

% this name can be edited
filename = 'TPMS.tif';

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% From here modify at your own risk

% Coordinate grid
[X,Y,Z] = ndgrid(1:n-1,1:n-1,1:nStructures*n-1);

% Normalized height (0 at bottom, 1 at top)
zNorm = (Z-1)/size(Z,3);

% Spatial coordinates
X = 2*pi*c*X/n;
Y = 2*pi*c*Y/n;
Z = 2*pi*c*Z/n;

% Same geometry, variable parameters
b = b_start + (b_end-b_start)*zNorm;
errore = errore_start + (errore_end-errore_start)*zNorm;

% Select geometry
f = geometryFunction(X,Y,Z,structures{1}) + b;
M = abs(f) < errore;

% Check number of selected structures
assert(numel(structures)==nStructures, 'nStructures must match the number of selected geometries');

% Position along the height, from 0 to nStructures-1
q = zNorm*(nStructures-1);

% Lower and upper geometry indices
idx1 = min(floor(q)+1,nStructures);
idx2 = min(idx1+1,nStructures);

% Interpolation coefficient
w = q-floor(q);
w(zNorm==1) = 0;

% Calculate the geometry fields
f = zeros(size(X));

for k = 1:nStructures

    fk = geometryFunction(X,Y,Z,structures{k}) + b;

    % Linear interpolation between consecutive geometries
    mask = (idx1==k);

    if k < nStructures
        fk2 = geometryFunction(X,Y,Z,structures{k+1}) + b;
        f(mask) = (1-w(mask)).*fk(mask) + w(mask).*fk2(mask);
    else
        f(mask) = fk(mask);
    end
end

M = abs(f) < errore;
M = logical(M);

% Porosity
rho = sum(M(:))/numel(M);

fprintf('Porosity = %.4f\n',rho);

% Visualization
volumeViewer(M);

delete(filename)

for k = 1:size(M,3)
    imwrite(uint8(255*M(:, :, k)), filename, 'WriteMode', 'append');
end

function f = geometryFunction(X,Y,Z,geometry)

switch geometry
    case 'Gyroid'
        f = sin(X).*cos(Y) + sin(Y).*cos(Z) + sin(Z).*cos(X);
    case 'Diamond'
        f = sin(X).*sin(Y).*sin(Z) + sin(X).*cos(Y).*cos(Z) + cos(X).*sin(Y).*cos(Z) + cos(X).*cos(Y).*sin(Z);
    case 'Primitive'
        f = cos(X) + cos(Y) + cos(Z);
    case 'IWP'
        f = 2*cos(X).*cos(Y) + 2*cos(Y).*cos(Z) + 2*cos(X).*cos(Z) - cos(2*X) - cos(2*Y) - cos(2*Z);
    case 'Nevious'
        f = 3*(cos(X)+cos(Y)+cos(Z)) + 4*cos(X).*cos(Y).*cos(Z);
    otherwise
        error('Unknown geometry: %s',geometry);
end
end